select * from dm_device_log


        and  dm_device_log.device_id = #{criteria.deviceId}


        and  dm_device_log.device_name LIKE CONCAT(#{criteria.deviceName},'%')


        and  dm_device_log.attribute_id = #{criteria.attributeId}


        and  dm_device_log.attribute_name LIKE CONCAT(#{criteria.attributeName},'%')


order by id DESC

